// Slack treats <!channel>, <!here>, <@user> and <url|label> in message text
// as live pings and links. Every value below is attacker-influenced (the
// sender typed name/company/email/phone, and the model's reasoning can
// quote them), so escape &, < and > exactly as Slack's docs say to.
// The routing fields (tier, needs_review, duplicate) pass through unchanged.
const esc = (v) => String(v ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

return $input.all().map((item) => ({
  json: {
    ...item.json,
    slack: {
      name: esc(item.json.name),
      company: esc(item.json.company || 'no company given'),
      reasoning: esc(item.json.reasoning),
      email: esc(item.json.email),
      phone: esc(item.json.phone),
    },
  },
}));
